record.field:
commission = {rate}
punctuality_discount = 0.00

if line._name == 'sale.order.line':
    punctuality_discount = (line.order_id.punctuality_discount/100)

if line._name == 'account.move.line':
    punctuality_discount = (line.move_id.invoice_punctuality_discount/100)

result = (line.fiscal_amount_untaxed * commission) * (1 - punctuality_discount)
